// Player-facing activity backed by named contract events. Balance snapshots and
// stake allocations are descriptions, not invented wallet transfers.
export const HISTORY_FILTERS = Object.freeze([
  ['buys', 'BUYS & PASSES'], ['jackpots', 'JACKPOTS'], ['pack-opens', 'PACK OPENS'],
  ['lootboxes', 'LUCKBOXES'], ['coinflip', 'COINFLIP'], ['craps', 'CRAPS'],
  ['degenerette', 'DEGENERETTE'], ['growth', 'GROWTH'], ['decimator', 'DECIMATOR'],
  ['incinerator', 'INCINERATOR'], ['redemptions', 'TOKEN BURNS'], ['salvage', 'SALVAGE'],
  ['rewards', 'REWARDS & REFERRALS'], ['funds', 'FUNDS & CLAIMS'], ['charity', 'CHARITY'],
]);
const raw = value => { try { return BigInt(value ?? 0); } catch { return 0n; } };
const token = (asset, value) => ({ asset, kind: ['ETH', 'STETH'].includes(asset) ? 'eth' : 'token', value: raw(value) });
const count = (asset, value) => ({ asset, kind: 'count', value: Number(value) || 0 });
const minus = (asset, value) => token(asset, -raw(value));
const level = a => `Level ${a.level ?? a.lvl ?? a.round}`;
// [category, title, description, proven asset changes]
const specs = {
  EntriesBought: ['buys', 'Tickets purchased', () => '', a => [minus('ETH', a.weiIn), count('TICKETS', Number(a.entryQuantityScaled) / 400)]],
  FoilPackBought: ['buys', 'Foil pack purchased', level, a => [minus('ETH', a.weiIn)]],
  WhalePassClaimed: ['buys', 'Whale pass claimed', a => `Starts at level ${a.startLevel}`, a => [count('HALF-PASS', -Number(a.halfPasses))]],
  PassActivated: ['buys', 'Pass activated', a => `${a.isWhale ? 'Whale' : 'Lazy'} · starts at level ${a.startLevel}`],
  CoinflipStakeUpdated: ['coinflip', 'Coinflip stake added', a => `Day ${a.day} · ${units(a.amount)} FLIP added`],
  CoinflipClaimState: ['coinflip', 'Coinflip balance updated', a => `${units(a.claimableStored)} FLIP claimable · ${units(a.autoRebuyCarry)} FLIP in auto-rebuy`],
  CoinflipAutoRebuyToggled: ['coinflip', 'Coinflip auto-rebuy', a => a.enabled ? 'Enabled' : 'Disabled'],
  CoinflipAutoRebuyStopSet: ['coinflip', 'Coinflip auto-rebuy limit', a => `${units(a.stopAmount)} FLIP`],
  CrapsDayReserved: ['craps', 'Craps day reserved', a => `Day ${a.day} · ${a.highRoller ? 'High roller' : 'Normal'}`],
  CrapsSlipPlaced: ['craps', 'Craps slip placed'],
  CrapsBetSettled: ['craps', 'Craps slip settled', a => `Bet #${a.betId}`, a => [token('FLIP', a.paid)]],
  CrapsBattlePaid: ['craps', 'Craps battle payout', a => `Bet #${a.betId}`, a => [token('FLIP', a.amount)]],
  CrapsHighRollerPaid: ['craps', 'Craps high roller payout', a => `Bet #${a.betId}`, a => [token('FLIP', a.amount)]],
  CrapsProgressivePaid: ['craps', 'Craps progressive payout', () => '', a => [token('FLIP', a.paid)]],
  CrapsDayWindowsUpgraded: ['craps', 'Craps windows upgraded', a => `Day ${a.day}`, a => [minus('FLIP', a.burned)]],
  CrapsNormalPassesConverted: ['craps', 'Craps passes converted', a => `${a.normalSpent} normal → ${a.highReceived} high roller`],
  CrapsPassesCredited: ['craps', 'Craps passes received', a => `${a.count} ${a.highRoller ? 'high roller' : 'normal'} passes`],
  CrapsBonusDonated: ['craps', 'Craps bonus funded', () => '', a => [minus('FLIP', a.amount)]],
  // DegenerusParimutuel.STAKE: 1,000 FLIP, in token wei like every FLIP value here.
  BetPlaced: ['growth', 'Growth bet placed', a => `${level(a)} · ${a.over ? 'OVER' : 'UNDER'}`, () => [minus('FLIP', 1000n * 10n ** 18n)]],
  BetClaimed: ['growth', 'Growth bet settled', level, a => [token('FLIP', a.payout)]],
  DecimatorBurn: ['decimator', 'Decimator burn', () => '', a => [minus('FLIP', a.amountBurned)]],
  // A battle winner is credited claimable ETH, or half whale passes in its place.
  DecimatorClaimed: ['decimator', 'Decimator prize paid', level, a => [token('ETH', a.amountWei), count('HALF-PASS', a.halfPasses)].filter(d => d.value !== 0 && d.value !== 0n)],
  DrawEntered: ['incinerator', 'WWXRP draw entered', a => `Day ${a.day}`, a => [minus('WWXRP', a.burnAmount)]],
  DrawClaimed: ['incinerator', 'WWXRP draw prize claimed', a => `Day ${a.day}`, a => [token('FLIP', a.prize)]],
  IncineratorEntered: ['incinerator', 'Incinerator entered', a => `Bracket ${a.bracket}`, a => [minus('WWXRP', a.burnAmount)]],
  IncineratorResolved: ['incinerator', 'Incinerator prize won', a => `Bracket ${a.bracket}`, a => [token('FLIP', a.flipAward)]],
  RedemptionSubmitted: ['redemptions', 'sDGNRS burn submitted', a => `Redemption period ${a.periodIndex}`, a => [minus('SDGNRS', a.sdgnrsAmount)]],
  RedemptionClaimed: ['redemptions', 'sDGNRS redemption claimed', () => '', a => [token('ETH', a.ethPayout), token('FLIP', a.flipPaid), { ...token('LOOTBOX', a.lootboxEth), kind: 'eth' }]],
  BurnThrough: ['redemptions', 'DGNRS burned', () => '', a => [minus('DGNRS', a.amount), token('ETH', a.ethOut), token('STETH', a.stethOut), token('FLIP', a.flipOut)]],
  FarFutureSwap: ['salvage', 'Tickets salvaged', a => `${a.lineCount} ticket levels swapped`, a => [token('ETH', a.ethCashWei), token('FLIP', a.flipTokens)]],
  QuestCompleted: ['rewards', 'Daily quest completed', a => `Day ${a.day}`, a => [token('FLIP', a.reward)]],
  LevelQuestCompleted: ['rewards', 'Level quest completed', level, a => [token('FLIP', a.reward)]],
  GrowthBetQuestCompleted: ['rewards', 'Growth quest completed', level, a => [token('FLIP', a.reward)]],
  BigRecordUpdated: ['rewards', 'Record bounty paid', () => '', a => [token('FLIP', a.paid), token('SDGNRS', a.sdgnrsPaid)]],
  MinerBounty: ['rewards', 'Mining bounty earned', () => '', a => [token('FLIP', a.flipAmount)]],
  AffiliateEarningsRecorded: ['rewards', 'Referral earnings updated'],
  // Audit b05ea7c50: a code registers its owner's permanent wallet ID (indexed by the owner).
  AffiliateOwnerRegistered: ['rewards', 'Referral code registered', a => `Wallet ID ${a.id}`],
  AffiliateDgnrsClaimed: ['rewards', 'Referral DGNRS claimed', level, a => [token('DGNRS', a.amount)]],
  ReferralUpdated: ['rewards', 'Referral updated', a => a.locked ? 'Referral locked in' : 'Referral set'],
  BingoClaimed: ['rewards', 'Bingo reward claimed', level, a => [token('FLIP', a.flipReward), token('DGNRS', a.dgnrsPaid)]],
  FoilMatchClaimed: ['rewards', 'Foil match claimed', a => `Day ${a.day} · tier ${a.tier}`],
  GoldenTicketFoil: ['rewards', 'Golden ticket foil reward', level, a => [token('FLIP', a.flipCredit)]],
  SubDrawWon: ['rewards', 'Subscription draw won', a => `Day ${a.day}`, a => [token('FLIP', a.flipAmount)]],
  WinningsClaimed: ['funds', 'ETH winnings withdrawn', () => '', a => [token('ETH', a.amount)]],
  AfkingFunded: ['funds', 'AFKING funded', () => '', a => [minus('ETH', a.amount)]],
  AfkingWithdrew: ['funds', 'AFKING funds withdrawn', () => '', a => [token('ETH', a.amount)]],
  AfkingFlipClaimed: ['funds', 'AFKING FLIP claimed', () => '', a => [token('FLIP', a.owed)]],
  LinkCreditRecorded: ['funds', 'LINK trade reward credited', () => 'FLIP added to coinflip stake', a => [token('FLIP', a.amount)]],
  MiddayRngCredited: ['funds', 'LINK contributed', () => 'LINK contributed to randomness funding', a => [minus('LINK', a.added)]],
  ReverseFlip: ['funds', 'Reverse flip purchased', () => '', a => [minus('FLIP', a.cost)]],
  DeadVrfClaimed: ['funds', 'VRF shutdown refund claimed', () => '', a => [token('ETH', a.amount)]],
  Voted: ['charity', 'Charity vote cast', a => `${level(a)} · choice ${a.slot}`],
};
function units(value) { return (Number(raw(value)) / 1e18).toLocaleString('en-US', { maximumFractionDigits: 4 }); }
export function historyEventNames(category) {
  return Object.keys(specs).filter(name => specs[name][0] === category);
}
export function historyEventActivities(events, address) {
  const owner = String(address || '').toLowerCase();
  return (Array.isArray(events) ? events : []).flatMap(event => {
    const spec = specs[event.name];
    if (!spec) return [];
    const a = event.args || {};
    if (event.name === 'CrapsHighRollerPaid' && a.bankrollRider) return []; // already in CrapsBetSettled.paid
    if (event.name === 'BigRecordUpdated' && raw(a.paid) === 0n && raw(a.sdgnrsPaid) === 0n) return [];
    // The facts route also matches operators/callers. Keep only the beneficiary
    // or payer named by this activity, not every wallet mentioned in its log.
    const subject = a.player ?? a.buyer ?? a.winner ?? a.donor ?? a.affiliate ?? a.miner ?? a.from ?? a.voter ?? a.caller;
    if (String(subject || '').toLowerCase() !== owner) return [];
    const [category, title, describe, deltas] = spec;
    return [{ id: `event:${event.transactionHash}:${event.logIndex}:${event.name}`, category,
      type: `${category}-activity`, title, detail: describe?.(a) || '',
      transactionHash: event.transactionHash, blockNumber: event.blockNumber, logIndex: event.logIndex,
      day: a.day ?? null, deltas: (deltas?.(a) || []).filter(delta => delta.value !== 0n && delta.value !== 0) }];
  });
}
